    spec = {"src": f"{H}/fr/{src}.png", "out": f"{OUT}/{name}.webp", "crop": [cx, cy, 1100, 600],
            "blur": [list(b) for b in COMMON + blur], "marks": marks, "width": 1000}
    p = f"{H}/specs/{name}.json"
    json.dump(spec, open(p, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    r = subprocess.run(["node", "scripts/guides/annotate-frame.cjs", p], cwd=WT, capture_output=True, text=True)
    print(name, (r.stdout.strip() or r.stderr.strip()[:300])[-60:])
